/* eslint-disable */
// @ts-nocheck
import { applyParamsToScript, cborToScript } from "@blaze-cardano/uplc";
import { type Script } from "@blaze-cardano/core";
import { Type, Exact, TPlutusData } from "@blaze-cardano/data";
import { type PlutusData } from "@blaze-cardano/core";
type Data = PlutusData;
type Int = bigint;
type ByteArray = string;
const PolicyId = Type.String();
type OutputReference = { output_index: bigint; transaction_id: string };

const Contracts = Type.Module({
  MultisigScript: Type.Union([
    Type.Object({
      Signature: Type.Object({
        key_hash: Type.String(),
      }, { ctor: 0n })
    }),
    Type.Object({
      AllOf: Type.Object({
        scripts: Type.Array(
          Type.Ref("MultisigScript")
        ),
      }, { ctor: 1n })
    }),
    Type.Object({
      AnyOf: Type.Object({
        scripts: Type.Array(
          Type.Ref("MultisigScript")
        ),
      }, { ctor: 2n })
    }),
    Type.Object({
      AtLeast: Type.Object({
        required: Type.BigInt(),
        scripts: Type.Array(
          Type.Ref("MultisigScript")
        ),
      }, { ctor: 3n })
    }),
    Type.Object({
      Before: Type.Object({
        time: Type.BigInt(),
      }, { ctor: 4n })
    }),
    Type.Object({
      After: Type.Object({
        time: Type.BigInt(),
      }, { ctor: 5n })
    }),
    Type.Object({
      Script: Type.Object({
        script_hash: Type.String(),
      }, { ctor: 6n })
    }),
  ]),
  Asset: Type.Tuple([
    Type.String(),
    Type.String(),
  ]),
  ProtocolRedeemer: Type.Union([
    Type.Literal("Mint", { ctor: 0n }),
    Type.Literal("Burn", { ctor: 1n }),
  ]),
  ProxyDatum: Type.Object({
    logic: Type.String(),
    settings: Type.Ref("Settings"),
  }, { ctor: 0n }),
  Registry: Type.Object({
    treasury: Type.String(),
    usdr: Type.String(),
  }, { ctor: 0n }),
  Settings: Type.Object({
    mint_permission: Type.Ref("MultisigScript"),
    burn_permission: Type.Ref("MultisigScript"),
    registry: Type.Ref("Registry"),
    reserve_token: Type.Ref("Asset"),
  }, { ctor: 0n }),
  TreasuryDatum: Type.Object({
    circulating_supply: Type.BigInt(),
  }, { ctor: 0n }),
});

export const MultisigScript = Contracts.Import("MultisigScript");
export type MultisigScript = Exact<typeof MultisigScript>;
export const Asset = Contracts.Import("Asset");
export type Asset = Exact<typeof Asset>;
export const ProtocolRedeemer = Contracts.Import("ProtocolRedeemer");
export type ProtocolRedeemer = Exact<typeof ProtocolRedeemer>;
export const ProxyDatum = Contracts.Import("ProxyDatum");
export type ProxyDatum = Exact<typeof ProxyDatum>;
export const Registry = Contracts.Import("Registry");
export type Registry = Exact<typeof Registry>;
export const Settings = Contracts.Import("Settings");
export type Settings = Exact<typeof Settings>;
export const TreasuryDatum = Contracts.Import("TreasuryDatum");
export type TreasuryDatum = Exact<typeof TreasuryDatum>;

export class V0_1ProtocolProtocolWithdraw {
  public Script: Script
  constructor(
    proxyPolicyId: PolicyId,
    trace?: boolean = false,
  ) {
    this.Script = cborToScript(
      applyParamsToScript(
        trace
          ?
          ""
          :
          "",
        Type.Tuple([
          PolicyId,
        ]),
        [
          proxyPolicyId,
        ],
      ),
      "PlutusV3"
    );
  }
}
